        """Reverse sorted input is sorted ascending."""
        assert bucketsort([4, 3, 2, 1, 0], 5) == [0, 1, 2, 3, 4]

    def test_bucketsort_with_duplicates(self):
        """Duplicates are preserved and sorted."""
        assert bucketsort([2, 1, 2, 0, 1, 2], 3) == [0, 1, 1, 2, 2, 2]

    def test_bucketsort_all_same_value(self):
        """All identical values remain identical."""
        assert bucketsort([1, 1, 1, 1], 3) == [1, 1, 1, 1]

    def test_bucketsort_zeros(self):
        """Multiple zeros are preserved."""
        assert bucketsort([0, 0, 0], 2) == [0, 0, 0]

    def test_bucketsort_unsorted_mixed(self):
        """Mixed unsorted input is sorted ascending."""
        assert bucketsort([3, 0, 2, 1, 3, 0], 4) == [0, 0, 1, 2, 3, 3]

    def test_bucketsort_k_larger_than_values(self):
        """k larger than max value still sorts correctly."""
        assert bucketsort([2, 0, 1], 10) == [0, 1, 2]

