import pytest

from minimum_spanning_tree import minimum_spanning_tree


def _total_weight(edges, weight_by_edge):
    """Helper: total weight of a set of edges given the weight mapping."""
    return sum(weight_by_edge[e] for e in edges)


def _is_spanning(edges, nodes):
    """Helper: check that the given edges connect all nodes (spanning tree)."""
    if not nodes:
        return True
    adjacency = {n: set() for n in nodes}
    for u, v in edges:
        adjacency[u].add(v)
        adjacency[v].add(u)
    start = next(iter(nodes))
    seen = {start}
    stack = [start]
    while stack:
        cur = stack.pop()
        for nxt in adjacency[cur]:
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    return seen == set(nodes)


def _is_acyclic(edges, nodes):
    """Helper: check that the given edges form a forest (no cycles)."""
    parent = {n: n for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for u, v in edges:
        ru, rv = find(u), find(v)
        if ru == rv:
            return False
        parent[ru] = rv
    return True


