def make_graph(edges):
    """Build nodes and successor lists from an edge dict keyed by (src, dst)."""
    nodes = {}

    def get_node(name):
        if name not in nodes:
            nodes[name] = Node(name)
        return nodes[name]

    for (src, dst) in edges:
        s = get_node(src)
        d = get_node(dst)
        if d not in s.successors:
            s.successors.append(d)
    return nodes


